import React, { useState } from 'react'
import { View, Text, TouchableOpacity } from 'react-native'
import { styles } from './styles'

export function Keyboard() {
    const [resultNumber, setResultNumber] = useState<string>('')

    function ButtonNumber({ number }: { number: string }) {
        function LimiterResult() {
            if (resultNumber.length < 8) {
                setResultNumber(resultNumber + number)
            }
        }

        return (
            <TouchableOpacity onPress={() => LimiterResult()}>
                <Text style={styles.textNumber}>{number}</Text>
            </TouchableOpacity>
        )
    }

    return (
        <View style={styles.container} >

            <View style={styles.containerResultNumber}>
                <Text style={styles.textResultNumber}>
                    {resultNumber[0] ? resultNumber[0] : '0' } 
                    {resultNumber[1] ? resultNumber[1] : '0' }
                    {resultNumber[2] ? resultNumber[2] : '0' }
                    {resultNumber[3] ? resultNumber[3] : '0' }
                </Text>
            </View>

            <View style={styles.containerNumber}>
                <ButtonNumber number={'1'} />
                <ButtonNumber number={'2'} />
                <ButtonNumber number={'3'} />
            </View>

            <View style={{
                flexDirection: 'row',
                justifyContent: 'space-around',
                alignItems: 'center'
            }}>
                <ButtonNumber number={'4'} />
                <ButtonNumber number={'5'} />
                <ButtonNumber number={'6'} />
            </View>

            <View style={{
                flexDirection: 'row',
                justifyContent: 'space-around',
                alignItems: 'center'
            }}>
                <ButtonNumber number={'7'} />
                <ButtonNumber number={'8'} />
                <ButtonNumber number={'9'} />
            </View>

            <View style={styles.containerButton}>
                <View style={styles.buttonLimpar}>
                    <Text style={styles.textButtonLimpar}>Limpar</Text>
                </View>

                <TouchableOpacity>
                    <ButtonNumber number={'0'} />
                </TouchableOpacity>

                <View style={styles.buttonConcluir}>
                    <Text style={styles.textButtonConcluir}>Concluir</Text>
                </View>
            </View>

        </View >
    );
};
